../energy/pbc.c:58:	pbc->reciprocal_basis[0][2] = inverse_volume*(pbc->basis[0][1]*pbc->basis[1][2] - pbc->basis[0][2]*pbc->basis[1][1]);
../energy/pbc.c:60:	pbc->reciprocal_basis[1][0] = inverse_volume*(pbc->basis[1][2]*pbc->basis[2][0] - pbc->basis[1][0]*pbc->basis[2][2]);
../energy/pbc.c:61:	pbc->reciprocal_basis[1][1] = inverse_volume*(pbc->basis[0][0]*pbc->basis[2][2] - pbc->basis[0][2]*pbc->basis[2][0]);
